### File: operators/ai-model-operator/internal/controller/aimodel_controller.go

3. Determine phase from pod state:
```go
func (r *AIModelReconciler) determinePhase(aimodel *AIModel, isvc *InferenceService, pod *corev1.Pod) string {
    if !aimodel.Spec.Enabled {
        return PhaseDisabled
    }

    if isvc == nil {
        return PhaseValidating
    }

    if pod == nil {
        return PhaseScheduling
    }

    if pod.Spec.NodeName == "" {
        return PhaseScheduling
    }

    // Check init container status
    for _, cs := range pod.Status.InitContainerStatuses {
        if cs.Name == "storage-initializer" && cs.State.Running != nil {
            return PhaseDownloading
        }
    }

    // Check main container status
    for _, cs := range pod.Status.ContainerStatuses {
        if cs.Name == "kserve-container" {
            if cs.State.Running != nil && !cs.Ready {
                return PhaseInitializing
            }
            if cs.Ready {
                return PhaseReady
            }
        }
    }

    return PhaseDeploying  // Fallback
}
```

