## Problem
Operators using GitOps have no CLI way to monitor model deployments. They must use kubectl to check status, which requires cluster access and K8s knowledge.

## Implementation Details

### File: services/ai-aas-cli/cmd/model_status.go (new)

1. Add status subcommand to model command:
```go
var modelStatusCmd = &cobra.Command{
    Use:   "status [model-name]",
    Short: "Show deployment status of a model",
    Long:  "Display detailed deployment status including phase, progress, and any blockers",
    Args:  cobra.ExactArgs(1),
    RunE:  runModelStatus,
}

func init() {
    modelCmd.AddCommand(modelStatusCmd)
    modelStatusCmd.Flags().BoolP("watch", "w", false, "Watch for status changes")
    modelStatusCmd.Flags().StringP("environment", "e", "development", "Target environment")
}
```

2. Implement status display:
```go
func runModelStatus(cmd *cobra.Command, args []string) error {
    modelName := args[0]
    watch, _ := cmd.Flags().GetBool("watch")
    env, _ := cmd.Flags().GetString("environment")

    client := api.NewClient(cfg)

    if watch {
        return watchModelStatus(client, modelName, env)
    }
    return showModelStatus(client, modelName, env)
}

func showModelStatus(client *api.Client, modelName, env string) error {
    status, err := client.GetModelDeploymentStatus(modelName, env)
    if err != nil {
        return err
    }

    // Display formatted status
    fmt.Printf("Model: %s\n", modelName)
    fmt.Printf("Environment: %s\n", env)
    fmt.Printf("Phase: %s (%s)\n", status.Phase, status.PhaseDuration)
    fmt.Println()

    // Timeline
    fmt.Println("Timeline:")
    for _, event := range status.Timeline {
        icon := "○"
        if event.Completed {
            icon = "✓"
        } else if event.InProgress {
            icon = "⏳"
        }
        fmt.Printf("  %s %-20s %s\n", icon, event.Phase, event.Message)
    }

    // Blockers
    if status.Blocked {
        fmt.Println()
        fmt.Printf("⚠ Blocked: %s\n", status.BlockedReason)
        fmt.Printf("  %s\n", status.BlockedResolution)
    }

    return nil
}
```

3. Add watch mode with terminal refresh:
```go
func watchModelStatus(client *api.Client, modelName, env string) error {
    ticker := time.NewTicker(2 * time.Second)
    defer ticker.Stop()

    for {
        // Clear screen and show status
        fmt.Print("\033[H\033[2J")
        if err := showModelStatus(client, modelName, env); err != nil {
            return err
        }
        fmt.Printf("\nWatching... (Ctrl+C to stop)\n")

        <-ticker.C
    }
}
```

